    await wait(`document.querySelector('#preview').contentDocument.querySelectorAll('.project-block').length === ${renderedBlockIds.length-1}`);
    assert.equal(await evaluate(`document.querySelector('.block[data-id=${JSON.stringify(firstBlockId)}]').classList.contains('inactive')`),true);
    await evaluate(`document.querySelector('.block[data-id=${JSON.stringify(firstBlockId)}] .block-visibility').click()`);
    await wait(`document.querySelector('#preview').contentDocument.querySelectorAll('.project-block').length === ${renderedBlockIds.length}`);
    await evaluate(`(()=>{const filter=document.querySelector('#block-filter');filter.value='images';filter.dispatchEvent(new Event('change',{bubbles:true}));})()`);
    assert.equal(await evaluate(`document.querySelectorAll('.block').length`),state.data.projects[0].content.filter(block=>['image','imagePair','image-pair','gallery'].includes(block.type)).length);
    assert.equal(await evaluate(`[...document.querySelectorAll('.block .drag-handle')].every(button=>button.disabled)`),true);
    await evaluate(`(()=>{const filter=document.querySelector('#block-filter');filter.value='all';filter.dispatchEvent(new Event('change',{bubbles:true}));})()`);
    assert.equal(await evaluate('document.querySelector("#preview").contentDocument.querySelector(".project-gallery").style.getPropertyValue("--gallery-columns")'),'2');
    await evaluate(`document.querySelector('#show-styles').click(); const groups=document.querySelectorAll('#style-controls .style-group'); const titleSize=groups[0].querySelector('input[type=number]'); titleSize.value='36'; titleSize.dispatchEvent(new Event('input',{bubbles:true})); const titleWeight=groups[0].querySelectorAll('select')[2]; titleWeight.value='700'; titleWeight.dispatchEvent(new Event('input',{bubbles:true})); const spacing=groups[1].querySelectorAll('input[type=number]'); spacing[2].value='44'; spacing[2].dispatchEvent(new Event('input',{bubbles:true})); const layout=groups[2]; const widthMode=layout.querySelector('.text-width-mode');widthMode.value='custom';widthMode.dispatchEvent(new Event('input',{bubbles:true})); const width=layout.querySelector('input[type=number]'); width.value='720'; width.dispatchEvent(new Event('input',{bubbles:true})); const alignments=layout.querySelectorAll('.style-control-row select'); for(const [control,value] of [[alignments[0],'center'],[alignments[1],'right'],[alignments[2],'center']]){control.value=value;control.dispatchEvent(new Event('input',{bubbles:true}));}`);
    await evaluate(`(()=>{const layout=document.querySelectorAll('#style-controls .style-group')[2];const gap=layout.querySelectorAll('input[type=number]')[1];gap.value='18';gap.dispatchEvent(new Event('input',{bubbles:true}));})()`);
    await wait(`document.querySelector('#preview').contentDocument.documentElement.style.getPropertyValue('--project-title-size') === '36px'`);
    assert.equal(await evaluate(`document.querySelector('#preview').contentDocument.documentElement.style.getPropertyValue('--project-block-gap')`),'44px');
    assert.equal(await evaluate(`document.querySelector('#preview').contentDocument.documentElement.style.getPropertyValue('--project-text-column-width')`),'720px');
    await evaluate(`(()=>{const mode=document.querySelector('.text-width-mode');mode.value='full';mode.dispatchEvent(new Event('input',{bubbles:true}));})()`);
    await wait(`document.querySelector('#preview').contentDocument.documentElement.style.getPropertyValue('--project-text-column-width') === '100%'`);
    assert.equal(await evaluate(`document.querySelectorAll('#style-controls .style-group')[2].querySelector('input[type=number]').disabled`),true);
    assert.ok(await evaluate(`(()=>{const doc=document.querySelector('#preview').contentDocument;const text=doc.querySelector('.project-text').getBoundingClientRect();const content=doc.querySelector('#project-content').getBoundingClientRect();return Math.abs(text.width-content.width)<1;})()`),'Full content width uses the project content container');
    await evaluate(`(()=>{const mode=document.querySelector('.text-width-mode');mode.value='custom';mode.dispatchEvent(new Event('input',{bubbles:true}));})()`);
    await wait(`document.querySelector('#preview').contentDocument.documentElement.style.getPropertyValue('--project-text-column-width') === '720px'`);
    assert.equal(await evaluate(`document.querySelectorAll('#style-controls .style-group')[2].querySelector('input[type=number]').value`),'720');
    await evaluate(`(()=>{const mode=document.querySelector('.text-width-mode');mode.value='full';mode.dispatchEvent(new Event('input',{bubbles:true}));})()`);
