    await evaluate(`(()=>{const controls=document.querySelectorAll('#style-controls .style-group')[2].querySelectorAll('.style-control-row select');controls[0].value='bottom';controls[0].dispatchEvent(new Event('input',{bubbles:true}));})()`); await wait(`document.querySelector('#preview').contentDocument.documentElement.style.getPropertyValue('--project-image-vertical-align') === 'end'`);
    await evaluate(`(()=>{const controls=document.querySelectorAll('#style-controls .style-group')[2].querySelectorAll('.style-control-row select');controls[0].value='center';controls[0].dispatchEvent(new Event('input',{bubbles:true}));controls[1].value='left';controls[1].dispatchEvent(new Event('input',{bubbles:true}));controls[2].value='right';controls[2].dispatchEvent(new Event('input',{bubbles:true}));})()`); await wait(`document.querySelector('#preview').contentDocument.documentElement.style.getPropertyValue('--project-image-horizontal-align') === 'flex-start' && document.querySelector('#preview').contentDocument.documentElement.style.getPropertyValue('--project-caption-align') === 'right'`);
