    await evaluate(`(()=>{const controls=document.querySelectorAll('#style-controls .style-group')[2].querySelectorAll('.style-control-row select');controls[1].value='right';controls[1].dispatchEvent(new Event('input',{bubbles:true}));controls[2].value='center';controls[2].dispatchEvent(new Event('input',{bubbles:true}));})()`);
    await evaluate(`(()=>{const group=document.querySelector('.gallery-spacing-styles');const linked=group.querySelector('input[type=checkbox]');const gaps=group.querySelectorAll('input[type=number]');linked.checked=false;linked.dispatchEvent(new Event('input',{bubbles:true}));gaps[0].value='20';gaps[0].dispatchEvent(new Event('input',{bubbles:true}));gaps[1].value='36';gaps[1].dispatchEvent(new Event('input',{bubbles:true}));})()`);
